insert into public.avengers_titles (slug, kind, chrono_order, title_pt, title_en, release_year, runtime_min, director, synopsis_pt, note) values
('wandavision', 'series', 1, 'WandaVision', 'WandaVision', 2021, null, 'Jac Schaeffer', 'Wanda e Visão vivem uma vida perfeita, como em uma sitcom nos subúrbios, até que a realidade começa a sair dos trilhos. A série prepara o terreno para Doutor Estranho no Multiverso da Loucura.', '9 episódios'),
('falcon-and-the-winter-soldier', 'series', 2, 'Falcão e o Soldado Invernal', 'The Falcon and the Winter Soldier', 2021, null, 'Kari Skogland', 'Sam Wilson e Bucky Barnes tentam entender o legado do Capitão América e o que fazer com ele. A série mostra como Sam assume o manto em Capitão América: Admirável Mundo Novo.', '6 episódios'),
('loki', 'series', 3, 'Loki', 'Loki', 2021, null, 'Michael Waldron', 'Capturado pela Autoridade de Variância Temporal, Loki descobre a existência da Linha do Tempo Sagrada — e sinais de que o multiverso está por vir.', '2 temporadas · 12 episódios'),
('what-if', 'series', 4, 'What If...?', 'What If...?', 2021, null, 'A.C. Bradley', 'Uma animação que explora o que aconteceria se momentos decisivos do MCU tivessem seguido outros caminhos. Uma viagem por realidades alternativas.', 'Animação · 3 temporadas'),
('x-men-97', 'series', 5, 'X-Men ''97', 'X-Men ''97', 2024, null, 'Beau DeMayo', 'Continuação da animação clássica dos anos 1990: sem Charles Xavier, os mutantes enfrentam o preconceito do mundo que juraram proteger.', 'Animação · 10 episódios na 1ª temporada'),
('x-men', 'xmen', 1, 'X-Men: O Filme', 'X-Men', 2000, 104, 'Bryan Singer', 'Temidos pelo mundo, os mutantes encontram abrigo na escola de Charles Xavier. Enquanto isso, Magneto prepara um plano contra a humanidade.', null),
('x2', 'xmen', 2, 'X-Men 2', 'X2: X-Men United', 2003, 134, 'Bryan Singer', 'Após um atentado contra o presidente, um coronel declara guerra aos mutantes. Para enfrentá-lo, os X-Men e a Irmandade precisam se unir.', null),
('x-men-first-class', 'xmen', 3, 'X-Men: Primeira Classe', 'X-Men: First Class', 2011, 132, 'Matthew Vaughn', 'Nos anos 1960, Charles Xavier e Erik Lehnsherr se unem para formar uma equipe de mutantes — até que suas diferenças os colocam em lados opostos.', null),
('x-men-days-of-future-past', 'xmen', 4, 'X-Men: Dias de um Futuro Esquecido', 'X-Men: Days of Future Past', 2014, 132, 'Bryan Singer', 'Wolverine viaja ao passado para impedir um futuro em que os mutantes são caçados e estão à beira da extinção.', null),
('deadpool', 'xmen', 5, 'Deadpool', 'Deadpool', 2016, 108, 'Tim Miller', 'Após um experimento que o deixa com poderes de cura e uma aparência transformada, Wade Wilson assume a identidade do mercenário tagarela Deadpool.', null),
('logan', 'xmen', 6, 'Logan', 'Logan', 2017, 137, 'James Mangold', 'Em um futuro em que os mutantes quase desapareceram, um Wolverine cansado cuida de um Professor X doente e protege uma menina com poderes semelhantes aos seus.', null),
('deadpool-2', 'xmen', 7, 'Deadpool 2', 'Deadpool 2', 2018, 119, 'David Leitch', 'Deadpool reúne a X-Force para proteger um jovem mutante do implacável Cable.', null);
